import { createRoot } from "react-dom/client";
import { FowlBounceGame } from "./FowlBounceComponent";

const puzzleRootElem = document.getElementById("fowl-bounce-puzzle-root");
if (puzzleRootElem) {
  const root = createRoot(puzzleRootElem);
  root.render(<FowlBounceGame />);
} else {
  console.error(
    "Could not mount because #fowl-bounce-puzzle-root was nowhere to be found",
  );
}
