import { markLocalTaskSolved } from "@hunt/puzzle-components";
import React, {
  useState,
  useEffect,
  useCallback,
  type CSSProperties,
  useRef,
} from "react";
import bird_img from "./assets/birdflippedbig.png";
import flap_sound from "./assets/bounce4_bfxr.wav";
import death_sound from "./assets/death3_spiral_simpler.mp3";
import pipe_sound from "./assets/pipe_coin2.wav";
import sound_off_icon from "./assets/sound_off.svg";
import sound_on_icon from "./assets/sound_on.svg";

const BIRD_IMAGE_PATH = bird_img;
const FLAP_SOUND_PATH = flap_sound;
const DEATH_SOUND_PATH = death_sound;
const PIPE_SOUND_PATH = pipe_sound;
const SOUND_ON_ICON = sound_on_icon;
const SOUND_OFF_ICON = sound_off_icon;

const DEBUG_MODE = false;

// Game configuration
const GAME_WIDTH = 480;
const GAME_HEIGHT = 640;
const BIRD_WIDTH = 102;
const BIRD_HEIGHT = 72;
const BIRD_LEFT_POSITION = 80;
const JUMP_VELOCITY = -10; // Negative = upward
const GRAVITY = 0.6; // Positive = downward acceleration
const MAX_FALL_VELOCITY = 12; // Terminal velocity
const PIPE_WIDTH = 70;
const PIPE_GAP = 160;
const PIPE_SPEED = 5;
const PIPE_SPAWN_INTERVAL = 1.2; // In seconds
const PIPE_COLOR = "#91db62ff";
const PIPE_BORDER_COLOR = "#2d6016";
const WINNING_SCORE = 10; // Score needed to complete the task

// Collision box reductions for more forgiving gameplay
const BIRD_HITBOX_WIDTH_REDUCTION = 0.495; // Reduce width by 49.5%
const BIRD_HITBOX_HEIGHT_REDUCTION = 0.4; // Reduce height by 40%
const BIRD_HITBOX_X_OFFSET = 5; // Horizontal offset (pixels, positive = right)
const BIRD_HITBOX_Y_OFFSET = 12; // Vertical offset (pixels, positive = down)
const PIPE_HITBOX_REDUCTION = 0.2; // Reduce pipe hitbox by 20%

// Styles
const gameContainerStyle: CSSProperties = {
  position: "relative",
  width: `${GAME_WIDTH}px`,
  height: `${GAME_HEIGHT}px`,
  backgroundImage:
    "linear-gradient(to bottom, #70c5ce 0%, #a6e6ef 50%, #70c5ce 100%)",
  overflow: "hidden",
  margin: "20px auto",
  border: "4.5px solid #000",
  color: "white",
  textShadow: "2px 2px 0px #000",
  cursor: "pointer",
  outline: "none",
  imageRendering: "pixelated",
};

const birdStyle = (top: number, rotation: number): CSSProperties => ({
  position: "absolute",
  top: `${top}px`,
  left: `${BIRD_LEFT_POSITION}px`,
  width: `${BIRD_WIDTH}px`,
  height: `${BIRD_HEIGHT}px`,
  backgroundImage: `url(${BIRD_IMAGE_PATH})`,
  backgroundSize: "contain",
  backgroundPosition: "center",
  backgroundRepeat: "no-repeat",
  transition: "transform 0.1s linear",
  transform: `rotate(${rotation}deg)`,
  zIndex: 10,
});

const pipeBaseStyle: CSSProperties = {
  position: "absolute",
  width: `${PIPE_WIDTH}px`,
  background: `linear-gradient(to right,
    #6ba84a 0%, #6ba84a 30%, ${PIPE_COLOR} 40%,  #b3f07a 100%
  )`,
  borderLeft: `4.5px solid ${PIPE_BORDER_COLOR}`,
  borderRight: `4.5px solid ${PIPE_BORDER_COLOR}`,
  boxSizing: "border-box",
  zIndex: 5,
};

const scoreStyle: CSSProperties = {
  position: "absolute",
  top: "20px",
  width: "100%",
  textAlign: "center",
  fontSize: "48px",
  fontWeight: "bold",
  zIndex: 20,
  WebkitTextStroke: "2px black",
};

const fpsStyle: CSSProperties = {
  position: "absolute",
  top: "10px",
  left: "10px",
  fontSize: "14px",
  zIndex: 50,
  fontFamily: "monospace",
  color: "#fff",
  textShadow: "1px 1px 0px #000",
  backgroundColor: "#000",
  padding: "4.5px 6px",
  border: "2px solid #fff",
};

const soundToggleStyle: CSSProperties = {
  position: "absolute",
  top: "10px",
  right: "10px",
  zIndex: 50,
  cursor: "pointer",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  gap: "0px",
  userSelect: "none",
  pointerEvents: "auto",
};

const overlayStyle: CSSProperties = {
  position: "absolute",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "rgba(0, 0, 0, 0.5)",
  display: "flex",
  flexDirection: "column",
  justifyContent: "center",
  alignItems: "center",
  textAlign: "center",
  zIndex: 30,
  pointerEvents: "none",
};

// Types
type GameState = "waiting" | "playing" | "gameOver";

type Pipe = {
  id: number;
  x: number;
  gapY: number;
};

// Helper functions
const generatePipe = (): Pipe => ({
  id: Date.now() + Math.random(),
  x: GAME_WIDTH,
  gapY: Math.floor(Math.random() * (GAME_HEIGHT - PIPE_GAP - 200)) + 100,
});

const Bird: React.FC<{ top: number; rotation: number }> = React.memo(
  ({ top, rotation }) => {
    return <div style={birdStyle(top, rotation)} />;
  },
);
Bird.displayName = "Bird";

const PipePair: React.FC<{ pipe: Pipe }> = React.memo(({ pipe }) => {
  const topPipeHeight = pipe.gapY - PIPE_GAP / 2;
  const bottomPipeTop = pipe.gapY + PIPE_GAP / 2;
  return (
    <>
      <div
        style={{
          ...pipeBaseStyle,
          left: `${pipe.x}px`,
          top: 0,
          height: `${topPipeHeight}px`,
          borderBottom: `4.5px solid ${PIPE_BORDER_COLOR}`,
        }}
      />
      <div
        style={{
          ...pipeBaseStyle,
          left: `${pipe.x}px`,
          top: `${bottomPipeTop}px`,
          bottom: 0,
          borderTop: `4.5px solid ${PIPE_BORDER_COLOR}`,
        }}
      />
    </>
  );
});
PipePair.displayName = "PipePair";

const FowlBounceGame: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>("waiting");
  const [birdPosition, setBirdPosition] = useState(
    GAME_HEIGHT / 2 - BIRD_HEIGHT / 2,
  );
  const [pipes, setPipes] = useState<Pipe[]>([]);
  const [score, setScore] = useState(0);
  const [fps, setFps] = useState(0);
  const [showFps, setShowFps] = useState(false);
  const [showHitboxes, setShowHitboxes] = useState(false);
  const [targetFps, setTargetFps] = useState(60);
  const [birdVelocity, setBirdVelocity] = useState(0);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [deathRotation, setDeathRotation] = useState(0);

  const pipePassedRef = useRef<Set<number>>(new Set());
  const gameContainerRef = useRef<HTMLDivElement>(null);
  const pipeSpawnTimerRef = useRef(0);
  const hasSubmittedRef = useRef(false);
  const birdVelocityRef = useRef(0);
  const birdPositionRef = useRef(GAME_HEIGHT / 2 - BIRD_HEIGHT / 2);
  const gameOverTimeRef = useRef<number>(0);
  const deathRotationRef = useRef(0);

  // Safari audio fix: Use Web Audio API and resume suspended AudioContext on user interaction
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioBuffersRef = useRef<Record<string, AudioBuffer>>({});
  const audioUnlockedRef = useRef(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const AudioCtor =
      window.AudioContext ||
      (window as Window & { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext;
    if (!AudioCtor) return;
    const ctx = new AudioCtor();
    audioContextRef.current = ctx;

    const loadSound = async (path: string, key: string) => {
      try {
        const response = await fetch(path);
        const arrayBuffer = await response.arrayBuffer();
        const decodedBuffer = await ctx.decodeAudioData(arrayBuffer);
        audioBuffersRef.current[key] = decodedBuffer;
      } catch (e) {
        if (DEBUG_MODE) console.error(`Failed to load ${key}`, e);
      }
    };

    void loadSound(FLAP_SOUND_PATH, "flap");
    void loadSound(DEATH_SOUND_PATH, "death");
    void loadSound(PIPE_SOUND_PATH, "pipe");

    return () => {
      void ctx.close().catch(() => undefined);
    };
  }, []);

  const playSound = useCallback(
    (key: string, volume: number) => {
      if (!soundEnabled || !audioContextRef.current) return;
      const buffer = audioBuffersRef.current[key];
      if (!buffer) return;

      try {
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        const gainNode = audioContextRef.current.createGain();
        gainNode.gain.value = volume;
        source.connect(gainNode);
        gainNode.connect(audioContextRef.current.destination);
        source.onended = () => {
          source.disconnect();
          gainNode.disconnect();
        };
        source.start(0);
      } catch (e) {
        if (DEBUG_MODE) console.error(e);
      }
    },
    [soundEnabled],
  );

  // Safari requires user interaction to resume suspended AudioContext
  const unlockAudio = useCallback(() => {
    if (audioUnlockedRef.current || !audioContextRef.current) return;
    if (audioContextRef.current.state === "suspended") {
      audioContextRef.current.resume().catch((e: unknown) => {
        if (DEBUG_MODE) console.error(e);
      });
    }
    audioUnlockedRef.current = true;
  }, []);

  const resetGame = useCallback(() => {
    setGameState("waiting");
    const initialPosition = GAME_HEIGHT / 2 - BIRD_HEIGHT / 2;
    setBirdPosition(initialPosition);
    birdPositionRef.current = initialPosition;
    setPipes([]);
    setScore(0);
    pipePassedRef.current.clear();
    pipeSpawnTimerRef.current = 0;
    birdVelocityRef.current = 0;
    setBirdVelocity(0);
    deathRotationRef.current = 0;
    setDeathRotation(0);
    gameContainerRef.current?.focus();
  }, []);

  const startGame = useCallback(() => {
    unlockAudio(); // Unlock on start
    resetGame();
    setGameState("playing");
    setPipes([generatePipe()]);
  }, [resetGame, unlockAudio]);

  const handlePointerDown = () => {
    unlockAudio(); // Unlock on interaction
    if (gameState === "playing") {
      playSound("flap", 0.3);
      birdVelocityRef.current = JUMP_VELOCITY;
      setBirdVelocity(JUMP_VELOCITY);
    } else if (gameState === "waiting") {
      startGame();
      playSound("flap", 0.3);
      birdVelocityRef.current = JUMP_VELOCITY;
      setBirdVelocity(JUMP_VELOCITY);
    }
  };

  const handlePointerUp = () => {
    // Not needed for flappy bird mechanics
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    // Game controls
    if (e.code === "Space") {
      e.preventDefault();
      unlockAudio(); // Unlock on interaction
      if (gameState === "playing") {
        playSound("flap", 0.3);
        birdVelocityRef.current = JUMP_VELOCITY;
        setBirdVelocity(JUMP_VELOCITY);
      } else if (gameState === "waiting") {
        startGame();
        playSound("flap", 0.3);
        birdVelocityRef.current = JUMP_VELOCITY;
        setBirdVelocity(JUMP_VELOCITY);
      } else if (gameState === "gameOver") {
        // Prevent accidental restart for 500ms after game over
        if (Date.now() - gameOverTimeRef.current >= 500) {
          resetGame();
        }
      }
    }

    // Sound toggle
    if (e.code === "KeyM") {
      e.preventDefault();
      setSoundEnabled((s) => !s);
    }

    // Debug keys
    if (DEBUG_MODE) {
      if (e.code === "KeyD") setShowFps((s) => !s);
      if (e.code === "KeyH") setShowHitboxes((s) => !s);
      if (e.code === "Digit1") setTargetFps(15);
      if (e.code === "Digit2") setTargetFps(30);
      if (e.code === "Digit3") setTargetFps(60);
    }
  };

  const handleKeyUp = (e: React.KeyboardEvent<HTMLDivElement>) => {
    // Not needed for flappy bird mechanics
    if (e.code === "Space") {
      e.preventDefault();
    }
  };

  useEffect(() => {
    // In gameOver state, we still want to run the loop for the death animation
    if (gameState === "waiting") return;

    let lastTime: number | null = null;
    let animationFrameId: number;
    let frameCount = 0;
    let fpsTimer = 0;
    let lastFrameTimestamp = 0;
    const targetFrameTime = 1000 / targetFps;

    const gameLoop = (timestamp: number) => {
      animationFrameId = requestAnimationFrame(gameLoop);
      const elapsed = timestamp - lastFrameTimestamp;
      if (targetFps < 60 && elapsed < targetFrameTime) return;
      lastFrameTimestamp = timestamp - (elapsed % targetFrameTime);

      if (lastTime === null) {
        lastTime = timestamp;
        return;
      }

      const deltaTime = (timestamp - lastTime) / 1000;
      const deltaMultiplier = deltaTime * 60;
      lastTime = timestamp;

      // FPS counter
      frameCount++;
      fpsTimer += deltaTime;
      if (fpsTimer >= 0.5) {
        setFps(Math.round(frameCount / fpsTimer));
        frameCount = 0;
        fpsTimer = 0;
      }

      // Bird movement with velocity and gravity
      birdVelocityRef.current += GRAVITY * deltaMultiplier;
      birdVelocityRef.current = Math.min(
        birdVelocityRef.current,
        MAX_FALL_VELOCITY,
      );

      birdPositionRef.current += birdVelocityRef.current * deltaMultiplier;
      setBirdPosition(birdPositionRef.current);
      setBirdVelocity(birdVelocityRef.current); // Update state for rotation

      // Death spiral animation
      if (gameState === "gameOver") {
        deathRotationRef.current += 15 * deltaMultiplier; // Rotate 15 degrees per frame at 60fps
        setDeathRotation(deathRotationRef.current);

        // Stop game loop once bird falls off screen
        if (birdPositionRef.current > GAME_HEIGHT + BIRD_HEIGHT) {
          cancelAnimationFrame(animationFrameId);
          return;
        }
      }

      // Pipe movement and spawning (only during playing)
      if (gameState === "playing") {
        setPipes((prev) => {
          let scoreUpdated = false;
          const newPipes = prev
            .map((p) => {
              const newX = p.x - PIPE_SPEED * deltaMultiplier;
              if (
                !pipePassedRef.current.has(p.id) &&
                newX + PIPE_WIDTH / 2 < BIRD_LEFT_POSITION
              ) {
                pipePassedRef.current.add(p.id);
                if (!scoreUpdated) {
                  setScore((s) => s + 1);
                  playSound("pipe", 0.3);
                  scoreUpdated = true;
                }
              }
              return { ...p, x: newX };
            })
            .filter((p) => p.x > -PIPE_WIDTH);
          return newPipes;
        });

        pipeSpawnTimerRef.current += deltaTime;
        if (pipeSpawnTimerRef.current > PIPE_SPAWN_INTERVAL) {
          pipeSpawnTimerRef.current = 0;
          setPipes((prev) => [...prev, generatePipe()]);
        }
      }
    };

    animationFrameId = requestAnimationFrame(gameLoop);
    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [gameState, targetFps, playSound]);

  // Calculate reduced collision boxes
  const getBirdHitbox = useCallback(() => {
    const widthReduction = BIRD_WIDTH * BIRD_HITBOX_WIDTH_REDUCTION;
    const heightReduction = BIRD_HEIGHT * BIRD_HITBOX_HEIGHT_REDUCTION;
    return {
      x: BIRD_LEFT_POSITION + widthReduction / 2 + BIRD_HITBOX_X_OFFSET,
      y: birdPosition + heightReduction / 2 + BIRD_HITBOX_Y_OFFSET,
      width: BIRD_WIDTH - widthReduction,
      height: BIRD_HEIGHT - heightReduction,
    };
  }, [birdPosition]);

  const getPipeHitbox = useCallback((pipe: Pipe) => {
    const reduction = PIPE_WIDTH * PIPE_HITBOX_REDUCTION;
    return {
      x: pipe.x + reduction / 2,
      width: PIPE_WIDTH - reduction,
      topHeight: pipe.gapY - PIPE_GAP / 2,
      bottomY: pipe.gapY + PIPE_GAP / 2,
    };
  }, []);

  // Collision detection
  useEffect(() => {
    if (gameState !== "playing") return;
    // Bird out of bounds
    if (birdPosition < 0) setBirdPosition(0);
    if (birdPosition > GAME_HEIGHT - BIRD_HEIGHT) {
      playSound("death", 0.4);
      gameOverTimeRef.current = Date.now();
      setGameState("gameOver");
      return;
    }

    const birdRect = getBirdHitbox();

    // Pipe collision
    for (const pipe of pipes) {
      const pipeHitbox = getPipeHitbox(pipe);
      if (
        birdRect.x < pipeHitbox.x + pipeHitbox.width &&
        birdRect.x + birdRect.width > pipeHitbox.x &&
        (birdRect.y < pipeHitbox.topHeight ||
          birdRect.y + birdRect.height > pipeHitbox.bottomY)
      ) {
        playSound("death", 0.4);
        gameOverTimeRef.current = Date.now();
        setGameState("gameOver");
        return;
      }
    }
  }, [birdPosition, pipes, gameState, getBirdHitbox, getPipeHitbox, playSound]);

  useEffect(() => {
    gameContainerRef.current?.focus();
  }, []);

  // Auto mark as solved when winning score is reached
  useEffect(() => {
    if (score >= WINNING_SCORE && !hasSubmittedRef.current) {
      hasSubmittedRef.current = true;
      const solved = markLocalTaskSolved("fowl_bounce");
      if (DEBUG_MODE && solved) {
        console.log("Task completed! Score:", score);
      }
    }
  }, [score]);

  const birdRotation =
    gameState === "gameOver" ? deathRotation : birdVelocity < 0 ? -20 : 30;

  return (
    <div
      ref={gameContainerRef}
      className="font-silkscreen"
      style={gameContainerStyle}
      tabIndex={0}
      role="button"
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerUp}
      onKeyDown={handleKeyDown}
      onKeyUp={handleKeyUp}
    >
      {DEBUG_MODE && showFps && (
        <div style={fpsStyle}>
          FPS: {fps} (Target: {targetFps === 60 ? "Max" : targetFps})
        </div>
      )}
      {/* Sound toggle button. M for keyboard shortcut */}
      <div
        style={soundToggleStyle}
        onClick={(e) => {
          e.stopPropagation();
          setSoundEnabled((s) => !s);
        }}
        /* onKeyDown handling needed to appease jsx-a11y/click-events-have-key-events lint */
        onKeyDown={(e) => {
          if (e.key === "m" || e.key === "M") {
            e.preventDefault();
            e.stopPropagation();
            setSoundEnabled((s) => !s);
          }
        }}
        role="button"
        tabIndex={-1}
      >
        <img
          src={soundEnabled ? SOUND_ON_ICON : SOUND_OFF_ICON}
          alt={soundEnabled ? "Sound on" : "Sound off"}
          style={{ width: "32px", height: "32px" }}
        />
        <div
          style={{
            fontSize: "14px",
            color: "#000",
            fontFamily: "inherit",
            fontWeight: "bold",
            textShadow: "none",
          }}
        >
          M
        </div>
      </div>
      <div style={scoreStyle}>{score}</div>
      <Bird top={birdPosition} rotation={birdRotation} />
      {pipes.map((pipe) => (
        <PipePair key={pipe.id} pipe={pipe} />
      ))}

      {DEBUG_MODE && showHitboxes && (
        <>
          {/* Bird hitbox */}
          {(() => {
            const hitbox = getBirdHitbox();
            return (
              <div
                style={{
                  position: "absolute",
                  left: `${hitbox.x}px`,
                  top: `${hitbox.y}px`,
                  width: `${hitbox.width}px`,
                  height: `${hitbox.height}px`,
                  border: "2px solid red",
                  zIndex: 100,
                  pointerEvents: "none",
                }}
              />
            );
          })()}
          {/* Pipe hitboxes */}
          {pipes.map((pipe) => {
            const hitbox = getPipeHitbox(pipe);
            return (
              <React.Fragment key={`hitbox-${pipe.id}`}>
                <div
                  style={{
                    position: "absolute",
                    left: `${hitbox.x}px`,
                    top: "0px",
                    width: `${hitbox.width}px`,
                    height: `${hitbox.topHeight}px`,
                    border: "2px solid yellow",
                    zIndex: 100,
                    pointerEvents: "none",
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    left: `${hitbox.x}px`,
                    top: `${hitbox.bottomY}px`,
                    width: `${hitbox.width}px`,
                    height: `${GAME_HEIGHT - hitbox.bottomY}px`,
                    border: "2px solid yellow",
                    zIndex: 100,
                    pointerEvents: "none",
                  }}
                />
              </React.Fragment>
            );
          })}
        </>
      )}

      {gameState === "waiting" && (
        <div style={overlayStyle}>
          <p
            style={{
              fontSize: "24px",
              margin: "10px 0",
              fontFamily: "inherit",
            }}
          >
            Click or press Space to bounce!
          </p>
          <p
            style={{
              fontSize: "14px",
              marginTop: "40px",
              fontFamily: "inherit",
            }}
          >
            Make it past <strong>{WINNING_SCORE}</strong> poles to complete your
            task
          </p>
          {DEBUG_MODE && (
            <p
              style={{
                fontSize: "12px",
                marginTop: "40px",
                color: "rgba(255,255,255,0.7)",
              }}
            >
              Debug: [D] Toggle FPS, [H] Toggle Hitboxes, [1-3] Set FPS Target
            </p>
          )}
        </div>
      )}

      {gameState === "gameOver" && (
        <div style={overlayStyle}>
          <h1 style={{ fontFamily: "inherit" }}>Game Over</h1>
          <h2 style={{ margin: "10px 0", fontFamily: "inherit" }}>
            Score: {score}
          </h2>
          <button
            onClick={(e) => {
              e.stopPropagation();
              // Prevent accidental restart for 350ms after game over
              if (Date.now() - gameOverTimeRef.current >= 350) {
                resetGame();
              }
            }}
            style={{
              padding: "12px 24px",
              fontSize: "18px",
              color: "#000",
              backgroundColor: "#ffd700",
              border: "4.5px solid #000",
              cursor: "pointer",
              marginTop: "20px",
              fontFamily: "inherit",
              pointerEvents: "auto",
              fontWeight: "bold",
              textShadow: "none",
            }}
          >
            Try Again
          </button>
        </div>
      )}
    </div>
  );
};

export { FowlBounceGame };
export default FowlBounceGame;
